  "contradictory_card_ids": ["C44","C55","C62"],
  "prediction_basis_card_ids": [
    "C01","C02","C10","C18","C20","C36","C40","C43","C50","C53","C69","C71",
    "C123","C128","C153","C184","C202",
    "C222","C249","C253","C256","C270"
  ],
  "claims": [
    {
      "claim": "Human gold-context records for the reference molecules are predominantly below F=20%: aliskiren 2-3%, argatroban lacking or negligible, alvimopan about 6%, melagatran 3-7%, epanolol 6-8%, and tegaserod about 10% fasted.",
      "card_ids": ["C01","C02","C10","C18","C20","C36","C40","C43","C50","C53","C69","C71"]
    },
    {
      "claim": "The only above-threshold F records are species- or prodrug-specific and do not transfer to the query: CDP323 >25% as an ester prodrug in preclinical species and epanolol about 40% in beagle dogs, while human values for those contexts remain 14% and 6-8%.",
      "card_ids": ["C14","C44","C55","C62"]
    },
    {
      "claim": "L4 permeability records for peptide comparators show low intestinal permeability in Caco-2 and in situ systems: hexarelin Caco-2 Papp below detection limit (<1.5e-7 cm/s) and rat SPIP permeability >10-fold lower than enalaprilat; DADLE AP-to-BL Papp 7.8e-8 cm/s with efflux ratios up to 11; FMLP Papp 1.3e-7 cm/s; desmopressin Papp 0.04e-6 cm/s.",
      "card_ids": ["C123","C127","C128","C136","C142","C153","C155","C168"]
    },
    {
      "claim": "L5 gut-wall records show efflux and intestinal metabolism as additional presystemic barriers: MC-LR has very low permeability with apical re-excretion and only 0.3-1.35% reaching basolateral; several compounds show efflux ratios >3; aliskiren gut-formed metabolites account for about 1% of dose.",
      "card_ids": ["C172","C184","C196","C202","C209","C218"]
    },
    {
      "claim": "L6 hepatic-clearance/metabolic-stability records for peptide(-mimetic) comparators show substantial hepatic intrinsic clearance or metabolic instability: saquinavir control CLint 112 ± 28 µL/min/mg (media loss) and 73.8 ± 17.9 (depletion) in rat, with ABT reducing it to 18.0 ± 3.5; KZR-616 HLM CLint 36.5 ± 1.80 µL/min/mg with NADPH and t1/2 76 min; bortezomib metabolism is dominated by CYP3A4 (79% by mAb inhibition). These support that any absorbed fraction of a peptide-like molecule would face significant presystemic/hepatic loss.",
      "card_ids": ["C222","C230","C249","C253","C256","C270"]
    },
    {
      "claim": "The query is far larger and more polar than these comparators (MW 4113 Da, logD -19.42, TPSA 1646 Å², 57 HBD, 56 HBA, neutral fraction 0), so the measured low-permeability and presystemic-loss direction applies a fortiori; no active uptake or prodrug mechanism is identified for this conjugate.",
      "card_ids": ["C123","C128","C153","C184","C202","C222","C249"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C222","C230","C249","C253","C256","C270"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability value for the query molecule itself.",
    "No matched oral-versus-intravenous exposure data for the query.",
    "No query-specific permeability, efflux, intestinal-metabolism, hepatic-clearance, or metabolic-stability measurement.",
    "No formulation, dose, or prandial-state information for the query.",
    "No data on possible active uptake, prodrug conversion, absorption-enhancer formulation, or specialized oral delivery for the query.",
    "L6 hepatic-clearance records are from other molecules/species/assays; transfer to the query is qualitative only."
  ],
  "decision_summary": "Predicted low and strengthened: human gold-context records are predominantly below F=20%; the only higher-F records are preclinical/prodrug-specific and non-transferable; L4 permeability is uniformly low with efflux; L5 gut-wall efflux/intestinal metabolism adds presystemic barriers; L6 hepatic-clearance/metabolic-stability records for peptide(-mimetic) comparators add mechanistic support for presystemic/hepatic loss. The query's extreme size and polarity make F>=20% unsupported."
}

